import { MeshBasicNodeMaterial, PlaneGeometry, Mesh, Group, Color } from 'three/webgpu';
import { uv, vec3, mix, smoothstep, time, uniform, texture, fract, sin, length } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const group = new THREE.Group();
  group.name = 'pricing-card-3';

  const cardW = 1.62;
  const cardH = 1.0;
  const geo = new THREE.PlaneGeometry(cardW, cardH);

  const inkColor = new THREE.Color(0x16161d);
  const accentColor = new THREE.Color(0xff2a38);
  const surfaceColor = new THREE.Color(0x0b0b10);

  // Card material — static composition: engineered gradient surface + subtle grain
  const mat = new MeshBasicNodeMaterial({ transparent: false });
  mat.colorNode = vec3(surfaceColor.r, surfaceColor.g, surfaceColor.b);

  const card = new THREE.Mesh(geo, mat);
  card.position.set(0, 0, 0);
  group.add(card);

  // Thin accent edge along the top (<=10% of frame)
  const accentGeo = new THREE.PlaneGeometry(cardW * 0.92, 0.02);
  const accentMat = new MeshBasicNodeMaterial({ color: accentColor });
  const accentStrip = new THREE.Mesh(accentGeo, accentMat);
  accentStrip.position.set(0, cardH * 0.5 - 0.01, 0.0025);
  group.add(accentStrip);

  // Ink-toned hairline along the bottom for engineered seam feel
  const edgeGeo = new THREE.PlaneGeometry(cardW * 0.92, 0.012);
  const edgeMat = new MeshBasicNodeMaterial({ color: inkColor, transparent: true, opacity: 0.92 });
  const edgeStrip = new THREE.Mesh(edgeGeo, edgeMat);
  edgeStrip.position.set(0, -cardH * 0.5 + 0.006, 0.0025);
  group.add(edgeStrip);

  // Subtle side rail (paper tone) to read as machined frame
  const railGeo = new THREE.PlaneGeometry(0.012, cardH * 0.92);
  const railMat = new THREE.MeshBasicNodeMaterial({ color: new THREE.Color(0x23232c), transparent: true, opacity: 0.85 });
  const railL = new THREE.Mesh(railGeo, railMat);
  railL.position.set(-cardW * 0.5 + 0.006, 0, 0.0025);
  group.add(railL);
  const railR = new THREE.Mesh(railGeo, railMat);
  railR.position.set(cardW * 0.5 - 0.006, 0, 0.0025);
  group.add(railR);

  // Weighted-settle entrance (scale only — adapter owns position)
  const tl = gsap.timeline();
  group.scale.set(0.94, 0.94, 0.94);
  tl.to(group.scale, {
    x: 1.0, y: 1.0, z: 1.0,
    duration: 0.9, ease: 'power4.out'
  });

  // Async-load the card texture and composite grain + engineered vignette over it
  const url = config.imageUrl;
  if (url) {
    ctx.textureLoader.loadTexture(url).then((tex) => {
      tex.colorSpace = THREE.SRGBColorSpace;
      tex.minFilter = THREE.LinearMipmapLinearFilter;
      tex.magFilter = THREE.LinearFilter;
      tex.generateMipmaps = true;
      tex.anisotropy = 4;
      tex.needsUpdate = true;

      const baseColor = texture(tex, uv());
      // Subtle animated grain
      const n = fract(sin(uv().x.mul(12.9898).add(uv().y.mul(78.233)).add(time.mul(0.35))).mul(43758.5453));
      const grain = n.sub(0.5).mul(0.022);
      // Engineered vignette — keeps form, kills flat-void
      const d = length(uv().sub(0.5));
      const vig = smoothstep(0.95, 0.38, d);
      mat.colorNode = baseColor.rgb.mul(mix(0.76, 1.0, vig)).add(vec3(grain));
      mat.needsUpdate = true;
    }).catch(() => {});
  }

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    tl.kill();
    geo.dispose();
    accentGeo.dispose();
    accentMat.dispose();
    edgeGeo.dispose();
    edgeMat.dispose();
    railGeo.dispose();
    railMat.dispose();
    mat.dispose();
  };

  return group;
}
